/* SKUDocket: isolated, synthetic browser preview. No external execution APIs. */
'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ico=(n='arrow-right')=>`<img class="icon" src="/assets/icons/ui/${n}.svg" alt="" aria-hidden="true" width="20" height="20">`;
const demoBadge=()=>'<span class="badge demo">DEMO — SYNTHETIC DATA</span>';
const badge=(t)=>`<span class="badge quiet">${esc(t)}</span>`;
const status=(t,k='pending')=>`<span class="status ${k}">${esc(t)}</span>`;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:0,maximumFractionDigits:2}).format(n);
const button=(text,action,kind='secondary',attrs='')=>`<button class="button ${kind}" data-action="${action}" ${attrs}><span>${text}</span>${ico()}</button>`;
const link=(text,url,kind='secondary')=>`<a class="button ${kind}" href="${url}"><span>${text}</span>${ico()}</a>`;
const alertBox=(title,copy,kind='warning')=>`<div class="alert ${kind}">${ico(kind==='success'?'circle-check':'circle-alert')}<div><b>${title}</b><span>${copy}</span></div></div>`;
const notice=(text,good=false)=>{const n=$('#panel-notice');if(n){n.textContent=text;n.classList.toggle('good',good);n.setAttribute('role','status');n.scrollIntoView({block:'nearest',behavior:'smooth'});}else toast(text)};
let toastTimer;
function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function readStorage(key,fallback){try{return JSON.parse(sessionStorage.getItem(key))??fallback}catch{return fallback}}
function writeStorage(key,v){try{sessionStorage.setItem(key,JSON.stringify(v));return true}catch{return false}}

const EVENT_NAMES=['landing_view','buyer_qualified','offer_13_selected','demo_open','evidence_view','override_view','price_view','pilot_request','consent_submit'];
const params=new URLSearchParams(location.search), source=['linkedin','broker-referral','forwarder-referral','importer-association','erp-integrator','ecommerce-integrator','direct'].includes(params.get('utm_source'))?params.get('utm_source'):null, campaign=['evidence-gap','broker-packet','repeat-lane','concept-13'].includes(params.get('utm_campaign'))?params.get('utm_campaign'):null;
function track(name,properties={}){
 if(!readStorage('skudocket-diagnostics-consent',false)||!EVENT_NAMES.includes(name))return;
 const allowed={};for(const k of ['selected_offer_id','source_id','area','action','qualification_method','preview_only','request_type'])if(properties[k]!=null)allowed[k]=properties[k];
 const anonymousSession=readStorage('skudocket-anonymous-session',null)||crypto.randomUUID();writeStorage('skudocket-anonymous-session',anonymousSession);const events=readStorage('skudocket-events',[]);events.push({anonymous_session_id:anonymousSession,event_id:crypto.randomUUID(),name,timestamp:new Date().toISOString(),page_id:document.body.dataset.route,concept_version:'1.0',demo_flag:true,source,campaign,...allowed});writeStorage('skudocket-events',events.slice(-200));
}
function download(data,name,type='text/plain'){const blob=new Blob([data],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}

// Navigation, dialogs, motion, and the real product film.
document.addEventListener('toggle',ev=>{if(ev.target instanceof HTMLDetailsElement){const summary=ev.target.querySelector(':scope>summary');summary?.setAttribute('aria-expanded',String(ev.target.open));}},true);
const menu=$('.menu-toggle'),nav=$('#main-nav');
menu?.addEventListener('click',()=>{const open=!nav.classList.contains('open');nav.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');});
$$('.nav-group').forEach(group=>group.addEventListener('toggle',()=>{if(group.open)$$('.nav-group').filter(g=>g!==group).forEach(g=>g.open=false);}));
document.addEventListener('click',ev=>{if(!ev.target.closest('.nav-group'))$$('.nav-group').forEach(g=>g.open=false);});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){const open=$('.nav-group[open]');if(open){open.open=false;$('summary',open).focus()}if(nav?.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open navigation');menu.focus()}}});
let dialogTrigger=null;
function openDialog(id,trigger){const dlg=$('#'+id);dialogTrigger=trigger??document.activeElement;dlg.showModal();const close=$('[data-close]',dlg);close?.focus();}
$$('[data-close]').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$$('dialog').forEach(d=>{d.addEventListener('close',()=>dialogTrigger?.focus());d.addEventListener('click',ev=>{if(ev.target===d){const r=d.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)d.close()}})});
$$('[data-open="analytics"]').forEach(b=>b.addEventListener('click',()=>{const check=$('#analytics-opt-in');check.checked=readStorage('skudocket-diagnostics-consent',false);$('#analytics-status').textContent=`${readStorage('skudocket-events',[]).length} local events. No external analytics transmission.`;openDialog('analytics-dialog',b);}));
$('#analytics-opt-in')?.addEventListener('change',ev=>{writeStorage('skudocket-diagnostics-consent',ev.target.checked);if(!ev.target.checked){sessionStorage.removeItem('skudocket-events');sessionStorage.removeItem('skudocket-anonymous-session');}$('#analytics-status').textContent=ev.target.checked?'Session-local diagnostics enabled. No form details are recorded.':'Diagnostics disabled and the event log cleared.';});
$('#clear-analytics')?.addEventListener('click',()=>{sessionStorage.removeItem('skudocket-events');$('#analytics-status').textContent='Local event log cleared.';});
$('#download-analytics')?.addEventListener('click',()=>{download(JSON.stringify(readStorage('skudocket-events',[]),null,2),'SKUDocket-local-preview-events.json','application/json');$('#analytics-status').textContent='Local log download prepared. Synthetic interactions are not demand evidence.';});
const motion=matchMedia('(prefers-reduced-motion: reduce)');
if('IntersectionObserver'in window&&!motion.matches){const obs=new IntersectionObserver(entries=>{entries.forEach(en=>{if(en.isIntersecting){en.target.classList.remove('offscreen');en.target.classList.add('revealed');obs.unobserve(en.target)}})},{threshold:.08});$$('[data-reveal]').forEach((el,i)=>{const rect=el.getBoundingClientRect();if(rect.top>innerHeight){el.classList.add('offscreen');obs.observe(el)}})}
motion.addEventListener('change',()=>{if(motion.matches)$$('.offscreen').forEach(el=>el.classList.remove('offscreen'));});
const video=$('#hero-video'),filmToggle=$('#film-toggle');let userPaused=false;
if(video){
 const setFilmButton=()=>{filmToggle.innerHTML=ico(video.paused?'play':'pause')+`<span>${video.paused?'Play the story':'Pause the story'}</span>`;filmToggle.setAttribute('aria-label',video.paused?'Play product animation':'Pause product animation');};
 video.addEventListener('error',()=>{video.closest('.film-view').classList.add('failed');filmToggle.hidden=true;});
 video.addEventListener('play',setFilmButton);video.addEventListener('pause',setFilmButton);
 const chapters=$$('[data-seek]');chapters.forEach(b=>b.addEventListener('click',()=>{userPaused=true;const seek=()=>{video.currentTime=Number(b.dataset.seek);video.pause();setFilmButton();};if(video.readyState>=1)seek();else{video.addEventListener('loadedmetadata',seek,{once:true});video.preload='metadata';video.load();}}));video.addEventListener('timeupdate',()=>{const starts=[0,3.2,6.8,10.5,14.1];chapters.forEach((b,i)=>b.setAttribute('aria-pressed',String(video.currentTime>=starts[i]&&video.currentTime<(starts[i+1]??18))));});
 filmToggle.addEventListener('click',()=>{if(video.paused){userPaused=false;video.play().catch(()=>toast('The animation could not play. The poster and transcript remain available.'));}else{userPaused=true;video.pause()}});
 if(!motion.matches){const filmObs=new IntersectionObserver(entries=>{entries.forEach(en=>{if(en.isIntersecting&&!userPaused&&!motion.matches)video.play().catch(()=>{});else video.pause()})},{threshold:.25});filmObs.observe(video);}
 motion.addEventListener('change',()=>{if(motion.matches){video.pause();video.currentTime=0;video.load();setFilmButton();}});
}
$$('[data-flip]').forEach(b=>b.addEventListener('click',()=>{const card=b.closest('.offer-card'),flipped=!card.classList.contains('is-flipped');card.classList.toggle('is-flipped',flipped);b.setAttribute('aria-pressed',String(flipped));b.innerHTML=ico('rotate-ccw')+(flipped?'View illustration':'View inputs');}));

// Real validation, with an explicitly unsent inquiry preview. PII never enters storage.
$$('[data-form]').forEach(form=>{
 const kind=form.dataset.form;
 if($('[name=offer]',form)&&/^[1-5]$/.test(params.get('offer')||''))$('[name=offer]',form).value=params.get('offer');
 if($('[name=topic]',form)&&['privacy','broker','accessibility','general'].includes(params.get('topic')))$('[name=topic]',form).value=params.get('topic');
 $('[name=offer]',form)?.addEventListener('change',ev=>{if(/^[1-5]$/.test(ev.target.value))track('offer_13_selected',{selected_offer_id:Number(ev.target.value),preview_only:true});});
 form.addEventListener('submit',ev=>{
  ev.preventDefault();let invalid=[];
  $$('[required]',form).forEach(el=>{let message='';if(el.type==='checkbox'&&!el.checked)message='Please choose this consent to preview the request.';else if(el.type==='email'&&!el.validity.valid)message='Enter a valid email address.';else if(el.type!=='checkbox'&&!el.value.trim())message='Please complete this field.';el.setAttribute('aria-invalid',String(!!message));const err=$('#error-'+el.name,form);if(err){err.textContent=message;if(message)el.setAttribute('aria-describedby',err.id);else el.removeAttribute('aria-describedby')}if(message)invalid.push(el);});
  const error=$('.form-error',form);if(invalid.length){error.textContent='Review the highlighted fields and required consent. Your values have been preserved.';invalid[0].focus();return;}error.textContent='';
  const fd=new FormData(form),request={preview_only:true,sent:false,stored:false,request_type:kind,privacy_version:'preview-2026-10-13',...Object.fromEntries(fd.entries())};
  const result=$('.form-result',form);result.innerHTML='<h4>Your request preview.</h4><p><strong>This has not been sent or saved.</strong> Review the details below or download a copy for your own records.</p><dl>'+['email','company','role','offer','broker_status','sku_band'].filter(k=>request[k]).map(k=>`<div><dt>${esc(k.replaceAll('_',' '))}</dt><dd>${esc(request[k])}</dd></div>`).join('')+'</dl><button type="button" class="button secondary download-request">Download request copy '+ico('download')+'</button>';
  $('.download-request',result).addEventListener('click',()=>download(JSON.stringify(request,null,2),'SKUDocket-unsent-'+kind+'-request.json','application/json'));
  if(kind==='pilot')track('pilot_request',{request_type:kind,preview_only:true,selected_offer_id:Number(fd.get('offer'))});
  // consent_submit and buyer_qualified are intentionally reserved for a future
  // connected operational store. A local preview is not a submitted lead.
  result.scrollIntoView({block:'nearest',behavior:motion.matches?'auto':'smooth'});result.setAttribute('tabindex','-1');result.focus();
 });
 // Enable only after the no-transmission handler is attached.
 $('fieldset',form)?.removeAttribute('disabled');
});

const BASE={schema:1,proposal:'unconfirmed',revision:1,originLoaded:false,originReviewed:false,screening:'unresolved',screenReason:'',brokerPersona:false,brokerReviewed:false,brokerReason:'',brokerQuestion:'',approved:false,exported:false,quantity:1000,unit:12,rateA:4,rateB:6,history:[]};
let state=readStorage('skudocket-demo-state',null);if(!state||state.schema!==1)state={...BASE,history:[]};
const save=()=>writeStorage('skudocket-demo-state',state);
const history=(action,reason,time='09:00',actor='Maya Chen')=>{const previous=state.history.at(-1)?.time;if(previous&&time<=previous){const [h,m]=previous.split(':').map(Number);const minutes=h*60+m+1;time=String(Math.floor(minutes/60)).padStart(2,'0')+':'+String(minutes%60).padStart(2,'0');}state.history.push({action,reason,time,actor,revision:state.revision});save();};
function invalidate(reason){if(state.approved||state.brokerReviewed){state.approved=false;state.brokerReviewed=false;state.exported=false;history('Affected review reopened',reason,'09:04');}}
function resetDemo(){state={...BASE,history:[]};sessionStorage.removeItem('skudocket-demo-state');renderDemo();toast('Synthetic fixture reset. All original holds and dates restored.');}
$$('[data-reset-demo]').forEach(b=>b.addEventListener('click',resetDemo));
const canonicalCost=()=>state.quantity===1000&&state.unit===12&&state.rateA===4&&state.rateB===6;
const blockers=()=>[!state.originReviewed?'Origin evidence has not been reviewed':null,state.screening!=='false-positive'?'Screening match remains unresolved or escalated':null,!state.brokerReviewed?'Broker review is not recorded':null,state.proposal!=='unconfirmed'?'The edited assumption requires a separately prepared packet':null,!canonicalCost()?'The edited cost scenario differs from the canonical PDF fixture':null].filter(Boolean);
const queue=[
 {sku:'HX-42',entry:'EN-104',supplier:'Harborside Works',status:'Held',owner:'Maya Chen',action:'Origin proof and screening review',updated:'02 Oct 09:00',due:'03 Oct 16:00'},
 {sku:'HX-43',entry:'EN-105',supplier:'Harborside Works',status:'Pending review',owner:'Maya Chen',action:'Compare revised specification',updated:'01 Oct 15:00',due:'03 Oct 12:00'},
 {sku:'BR-18',entry:'EN-106',supplier:'North Quay Components',status:'Evidence collected',owner:'Iris Patel',action:'Check invoice linkage',updated:'01 Oct 11:00',due:'03 Oct 15:00'},
 {sku:'CL-07',entry:'EN-107',supplier:'Maple Foundry',status:'Held',owner:'Iris Patel',action:'Missing valuation explanation',updated:'01 Oct 16:00',due:'04 Oct 12:00'},
 {sku:'PN-21',entry:'EN-108',supplier:'North Quay Components',status:'Broker review',owner:'Noah Reed',action:'Review rationale',updated:'02 Oct 08:00',due:'03 Oct 10:00'},
 {sku:'WS-09',entry:'EN-109',supplier:'Maple Foundry',status:'Exported',owner:'Noah Reed',action:'Packet v1 exported; review next supplier revision',updated:'01 Oct 10:00',due:'On supplier change'},
 {sku:'FT-33',entry:'EN-110',supplier:'Harborside Works',status:'Rejected proposal',owner:'Noah Reed',action:'Product function contradicts suggestion',updated:'01 Oct 13:00',due:'03 Oct 14:00'},
 {sku:'CP-14',entry:'EN-111',supplier:'Lakeshore Fabrication',status:'Pending review',owner:'Maya Chen',action:'Supplier-origin inconsistency',updated:'02 Oct 08:30',due:'04 Oct 10:00'},
 {sku:'SP-26',entry:'EN-112',supplier:'Lakeshore Fabrication',status:'Exported',owner:'Noah Reed',action:'Packet v2 exported; review next supplier revision',updated:'01 Oct 14:00',due:'On supplier change'},
 {sku:'RD-11',entry:'EN-113',supplier:'Maple Foundry',status:'Broker review',owner:'Iris Patel',action:'Stale tariff fixture: re-review required',updated:'02 Oct 08:45',due:'03 Oct 11:00'}
];
const statusKind={'Held':'held','Pending review':'pending','Evidence collected':'collected','Broker review':'review','Exported':'exported','Rejected proposal':'rejected'};
function queueState(row){return row.sku==='HX-42'?(state.exported?'Exported':state.approved?'Broker review':state.originReviewed&&state.screening==='false-positive'?'Broker review':'Held'):row.status;}
const palette=['#835510','#667F99','#3B617D','#82728E','#31604F','#AF5A56'];
function renderQueue(){
 if(!$('#queue-table'))return;
 const counts=Object.fromEntries(Object.keys(statusKind).map(k=>[k,queue.filter(r=>queueState(r)===k).length]));
 let offset=0;const arcs=Object.entries(counts).map(([k,n],i)=>{const len=n*10,arc=`<circle cx="70" cy="70" r="49" pathLength="100" fill="none" stroke="${palette[i]}" stroke-width="13" stroke-dasharray="${len} ${100-len}" stroke-dashoffset="${-offset}" transform="rotate(-90 70 70)"></circle>`;offset+=len;return arc}).join('');
 $('#queue-overview').innerHTML='<div class="queue-overview"><div class="queue-stat-grid">'+Object.entries(counts).map(([k,n])=>`<div class="queue-stat"><span>${k}</span><strong>${n}</strong></div>`).join('')+'</div><div class="queue-chart"><svg viewBox="0 0 140 140" role="img" aria-label="Synthetic queue: '+Object.entries(counts).map(([k,n])=>`${n} ${k}`).join(',')+'">'+arcs+'<text x="70" y="67" text-anchor="middle" fill="#263C4C" font-family="Source Serif 4,serif" font-size="29">10</text><text x="70" y="87" text-anchor="middle" fill="#5B6870" font-family="Public Sans,sans-serif" font-size="8">DEMO SKUs</text></svg><div class="chart-labels">'+demoBadge()+Object.entries(counts).map(([k,n],i)=>`<div><i style="background:${palette[i]}"></i>${n} ${k}</div>`).join('')+'</div></div></div>';
 const term=$('#queue-search').value.toLowerCase().trim(),filter=$('#queue-filter').value;
 const rows=queue.filter(r=>(filter==='all'||queueState(r)===filter)&&`${r.sku} ${r.supplier} ${r.entry}`.toLowerCase().includes(term));
 $('#queue-count').textContent=`${rows.length} of 10 synthetic records`;
 $('#queue-table').innerHTML=rows.length?'<div class="table-scroll"><table class="queue-table"><caption>Fictional review queue · All times UTC, October 2026</caption><thead><tr><th>SKU / entry</th><th>Supplier</th><th>State</th><th>Owner</th><th>Next action</th><th>Review</th></tr></thead><tbody>'+rows.map(r=>`<tr><td><b>${r.sku}</b><small>${r.entry} · v1 fixture</small>${demoBadge()}</td><td>${r.supplier}</td><td>${status(queueState(r),statusKind[queueState(r)])}</td><td>${r.owner}</td><td>${r.action}<small>Updated ${r.updated} UTC · Due ${r.due}${r.due.includes('Oct')?' UTC':''}</small></td><td>${r.sku==='HX-42'?'<a class="row-link" href="/demo/skus/hx-42">Open record '+ico()+'</a>':`<button class="row-link" data-row="${r.sku}">View record ${ico()}</button>`}</td></tr>`).join('')+'</tbody></table></div>':'<div class="empty-state"><h3>No matching synthetic records.</h3><p>Try another SKU, supplier, or review state.</p><button class="button secondary" id="clear-queue">Clear filters</button></div>';
 $$('[data-row]').forEach(b=>b.addEventListener('click',()=>openQueueRecord(b.dataset.row,b)));
 $('#clear-queue')?.addEventListener('click',()=>{$('#queue-search').value='';$('#queue-filter').value='all';renderQueue()});
}
$('#queue-search')?.addEventListener('input',renderQueue);$('#queue-filter')?.addEventListener('change',renderQueue);
function openQueueRecord(sku,trigger){const r=queue.find(x=>x.sku===sku);$('#evidence-title').textContent=`${r.sku} / ${r.entry}`;$('#evidence-body').innerHTML=`<h3>${r.supplier}</h3><p>${status(r.status,statusKind[r.status])}</p><dl><div><dt>Fictional owner</dt><dd>${r.owner}</dd></div><div><dt>Next action</dt><dd>${r.action}</dd></div><div><dt>Updated / due</dt><dd>${r.updated} UTC / ${r.due} ${r.due.includes('Oct')?'UTC':''}</dd></div><div><dt>Source specification</dt><dd>SPEC-${r.sku.replace('-','')}-v1</dd></div><div><dt>Invoice fixture reference</dt><dd>INV-${r.entry.replace('-','')}-v1</dd></div></dl><div class="evidence-quote">${r.sku==='FT-33'?'The proposed product-function assumption contradicts the fictional specification. The proposal stays rejected; the owner needs to revise the explanation.':r.sku==='RD-11'?'Tariff fixture v0 is stale for the example date. The earlier source is preserved, and a new review is required before updating the packet.':'This supporting queue record has an assigned review task. The full deterministic click path is available for HX-42.'}</div><p class="fineprint">Supporting record only. No real documents, transaction amounts, or external actions.</p>${link('Open the full HX-42 example','/demo/skus/hx-42')}`;openDialog('evidence-dialog',trigger);track('evidence_view',{area:'queue',preview_only:true});}

