 'SPEC-HX42-v1':{title:'Product specification',type:'Fictional product evidence',date:'28 Sep 2026',body:'Stainless threaded fastener assembly. Component composition is stated in the fictional specification. Full imported assembly function is not established; that missing fact needs review.',published:'28 Sep 2026',effective:'Fixture product revision v1',retrieved:'01 Oct 2026, 09:00 UTC (simulated)'},
 'DRAW-HX42-v1':{title:'Technical drawing',type:'Fictional product evidence',date:'28 Sep 2026',body:'Drawing identifies a threaded steel component and associated assembly parts. It does not establish how the complete good is presented at import or resolve its full function.',published:'28 Sep 2026',effective:'Drawing revision v1',retrieved:'01 Oct 2026, 09:00 UTC (simulated)'},
 'INV-HW-104-v1':{title:'Invoice fixture',type:'Fictional commercial record',date:'28 Sep 2026',body:'Alder Import Co / Harborside Works. 1,000 units × $12.00 = $12,000. Invoice date 28 Sep 2026. This is not a real invoice.',published:'28 Sep 2026',effective:'Invoice v1',retrieved:'01 Oct 2026, 09:00 UTC (simulated)'},
 'PRIOR-EN104-v1':{title:'Prior-entry reference',type:'Fictional historical comparison',date:'30 Sep 2026',body:'EN-104 is an invented prior-entry reference. A previous entry is a comparison artifact; it does not prove the proposed classification or value is correct.',published:'30 Sep 2026',effective:'Historical comparison v1',retrieved:'01 Oct 2026, 09:00 UTC (simulated)'},
